INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(141, 'Juruteknik Mesin Ladang', 'Juruteknik yang membaiki mesin dan jentera di ladang kelapa sawit (watak rekaan).', 'Menjaga mesin ladang supaya ekonomi komersial berjalan lancar.', 'juruteknik_mesin_ladang_sawit.png'),
(142, 'Inspektor Kilang Automotif', 'Inspektor yang memeriksa mutu kereta dan motosikal di kilang (watak rekaan).', 'Memastikan barangan buatan Malaysia lulus pemeriksaan mutu.', 'inspektor_kilang_automotif.png'),
(143, 'Pemilik Kedai Jenama Malaysia', 'Pemilik kedai yang menjual barangan jenama Malaysia dengan penuh bangga (watak rekaan).', 'Memperkenalkan produk pertanian, petroleum dan automotif buatan Malaysia kepada pelanggan.', 'peniaga_rumah_kedai.png'),
(144, 'Pak Tani Dahulu', 'Petani tua yang masih setia dengan cangkul dan sabit (watak rekaan).', 'Mewakili ekonomi tradisional yang dijalankan kecil-kecilan.', 'petani_lama.png'),
(145, 'Petani Moden', 'Petani yang mengusahakan ladang dengan mesin dan jentera penuai (watak rekaan).', 'Mewakili ekonomi komersial secara perladangan.', 'petani.png'),
(146, 'Penoreh Getah', 'Penoreh getah yang peramah dan rajin bekerja (watak rekaan).', 'Mewakili industri getah dan kelapa sawit.', 'penoreh_getah.png'),
(147, 'Jurutera Pelantar Minyak', 'Jurutera yang bertugas di pelantar minyak di tengah laut (watak rekaan).', 'Mewakili industri petroleum dan gas.', 'jurutera_pelantar_minyak.png'),
(148, 'Pemandu Pelancong', 'Pemandu pelancong yang ramah dan bersemangat bercerita tentang negara (watak rekaan).', 'Mewakili industri pelancongan dan kempen Tahun Melawat Malaysia.', 'gadis_sarawak.png'),
(149, 'Peniaga E-Dagang', 'Peniaga yang menjual barangan melalui telefon dan laman web (watak rekaan).', 'Mewakili perdagangan e-dagang yang semakin berkembang.', 'ibu_kini.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(801, 'Dari Cangkul ke Jentera: Kembara Juruteknik', 8, 'Masuki peranan juruteknik mesin ladang yang mengembara dari sawah bercangkul ke pelantar minyak dan bandar moden. Dalam perjalananmu kau mengenali ekonomi tradisional dan komersial, industri pemacu, barangan jenama Malaysia serta pencapaian pembangunan, perhubungan dan perdagangan.'),
(802, 'Pemeriksaan Mutu Ekonomi Negara', 8, 'Masuki peranan inspektor kilang yang memeriksa mutu ekonomi negara dengan borang dan cop LULUS. Dalam setiap pemeriksaan kau mengenali ekonomi tradisional dan komersial, industri pemacu, barangan jenama Malaysia serta pencapaian pembangunan, perhubungan dan perdagangan.'),
(803, 'Kedai Jenama Malaysia: Cerita Setiap Rak', 8, 'Masuki peranan pemilik kedai jenama Malaysia yang menceritakan kisah di sebalik setiap rak. Dalam kedaimu kau mengenali ekonomi tradisional dan komersial, industri pemacu, barangan jenama Malaysia serta pencapaian pembangunan, perhubungan dan perdagangan.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e8_n1_s1', 'Sawah kecil bertali air dengan rumah kayu dan cangkul tersandar di tepi pagar. Kau, juruteknik, membongkok melihat alat-alat mudah sementara Pak Tani Dahulu dan Petani Moden bergilir bercerita.', 1, 801, 'ekonomi_tradisional.png'),
('e8_n1_s2', 'Hutan getah yang redup dengan mangkuk susu getah di setiap batang. Kau, juruteknik, menyandar pada sebatang pokok sementara Penoreh Getah dan Petani Moden menerangkan kesan industri ini.', 2, 801, 'industri_getah_dan_kepala_sawit.png'),
('e8_n1_s3', 'Pelantar minyak gergasi di tengah laut yang berkilau di bawah matahari. Kau, juruteknik, berdiri di dek bersama Jurutera Pelantar Minyak sambil mendengar deruan ombak dan enjin.', 3, 801, 'industri_petroleum_dan_gas.png'),
('e8_n1_s4', 'Kilang kereta yang bersih dengan lengan robot dan barisan kereta yang bergerak. Kau, juruteknik, berdiri di tepi barisan pemasangan sementara Inspektor Kilang dan Pemandu Pelancong bergilir bercerita.', 4, 801, 'industri_automotif.png'),
('e8_n1_s5', 'Rak kedai yang penuh dengan minyak masak, buah, tong gas dan model kenderaan di bawah bendera Malaysia. Kau, juruteknik, meneliti setiap produk sementara Pemilik Kedai dan Petani Moden menerangkannya.', 5, 801, 'barangan_buatan_malaysia.png'),
('e8_n1_s6', 'Pemandangan bandar moden dengan menara pencakar langit, jambatan layang dan gudang e-dagang. Kau, juruteknik, merenung dari balkoni sementara Peniaga E-Dagang menunjukkan hasil pembangunan negara.', 6, 801, 'pencapaian_ekonomi_perhubungan_dan_perdagangan.png'),
('e8_n2_s1', 'Ladang kelapa sawit yang luas dengan traktor dan jentera penuai yang sedang bekerja. Kau, inspektor, membawa papan klip sementara Petani Moden dan Pak Tani Dahulu menunggu untuk diperiksa.', 1, 802, 'ekonomi_komersial.png'),
('e8_n2_s2', 'Ladang getah yang luas dengan pondok pekerja di tengahnya. Kau, inspektor, mengangkat papan klip sambil Penoreh Getah dan Petani Moden menerangkan kesan industri ini.', 2, 802, 'ladang.png'),
('e8_n2_s3', 'Litar perlumbaan motosikal yang riuh dengan bendera dan penonton. Kau, inspektor, berdiri di tepi pagar litar sementara Jurutera Pelantar Minyak menunjuk papan iklan yang luntur.', 3, 802, 'sukan_permotoran.png'),
('e8_n2_s4', 'Pantai senja dengan air terjun, jambatan gantung hutan dan monyet belanda di batang kayu. Kau, inspektor kilang, melangkah ke hutan sementara Pemandu Pelancong mengajak melihat tarikan negara.', 4, 802, 'industri_pelancongan.png'),
('e8_n2_s5', 'Barisan pemeriksaan terakhir di kilang kereta dengan lengan robot dan kenderaan yang bergerak. Kau, inspektor, berdiri dengan papan klip sementara Pemilik Kedai Jenama Malaysia menunjukkan produk untuk diperiksa.', 5, 802, 'industri_automotif.png'),
('e8_n2_s6', 'Bandar moden dengan menara pencakar langit, jambatan layang dan gudang e-dagang. Kau, inspektor, membuat pemeriksaan terakhir dari atas bangunan sementara Peniaga E-Dagang menjadi pemandu.', 6, 802, 'pencapaian_ekonomi_perhubungan_dan_perdagangan.png'),
('e8_n3_s1', 'Kampung dengan sawah hijau dan rumah kayu di tengah-tengahnya. Kau, pemilik kedai, berjalan di tepi sawah mencari asal-usul barangan yang kau jual sementara Pak Tani Dahulu dan Petani Moden menyambut.', 1, 803, 'kampung_dan_pedalaman.png'),
('e8_n3_s2', 'Ladang kelapa sawit dengan traktor dan jentera penuai. Kau, pemilik kedai, mengutip buah kelapa sawit sementara Petani Moden dan Penoreh Getah menerangkan kesan industri ini kepada negara.', 2, 803, 'ekonomi_komersial.png'),
('e8_n3_s3', 'Pelantar minyak di tengah laut yang terang di bawah matahari. Kau, pemilik kedai, menjenguk dari bot kecil sementara Jurutera Pelantar Minyak menerangkan dari dek.', 3, 803, 'industri_petroleum_dan_gas.png'),
('e8_n3_s4', 'Litar perlumbaan antarabangsa yang meriah dengan kereta berwarna-warni dan penonton dari seluruh dunia. Kau, pemilik kedai, menyelit di pagar litar sementara Pemandu Pelancong dan Inspektor Kilang bergilir bercerita.', 4, 803, 'formula_one_formula_e.png'),
('e8_n3_s5', 'Rak kedai yang penuh dengan minyak masak, durian, nanas, tong gas dan model kenderaan di bawah bendera Malaysia. Kau, pemilik kedai, membetulkan susunan produk sementara tiga rakan menjenguk.', 5, 803, 'barangan_buatan_malaysia.png'),
('e8_n3_s6', 'Bilik pandang yang menghadap ufuk bandar dengan meja peta dunia dan deretan bendera. Kau, pemilik kedai, merenung keluar sementara Peniaga E-Dagang menerangkan hubungan kedaimu dengan dunia.', 6, 803, 'malaysia_dan_dunia_serantau.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(801, 'e8_n1_s1', 'Misi Sawah: Bukti Ekonomi Tradisional', 'Cari bukti ekonomi tradisional pada gambar sawah ini.', '2', 'Membezakan ekonomi tradisional dan ekonomi komersial.', '{"bgImage": "../assets/gameAsset/background/ekonomi_tradisional.png", "hotspots": [{"name": "Cangkul di tepi petak: peralatan mudah ekonomi tradisional", "top": "80%", "left": "20%"}, {"name": "Cangkul kedua di tepi pagar: modal kecil dan alat sederhana", "top": "75%", "left": "86%"}, {"name": "Rumah kayu petani: hasil untuk keperluan sendiri dan keluarga", "top": "28%", "left": "15%"}, {"name": "Petak sawah kecil: dijalankan secara kecil-kecilan", "top": "45%", "left": "57%"}], "aftermath": "Bukti ekonomi tradisional tersalah cari. Juruteknik menyangka sawah kecil itu ladang komersial.", "turns": [{"after": 7, "options": [{"text": "Keperluan sendiri dan keluarga.", "isCorrect": true, "reaction": "Tepat, juruteknik! Pak Tani tersenyum dan mengetuk cangkulnya dua kali."}, {"text": "Kegunaan tempatan dan eksport.", "isCorrect": false, "reaction": "Itu hasil ekonomi komersial, juruteknik! Pak Tani ketawa sambil menggeleng."}, {"text": "Pasaran antarabangsa sahaja.", "isCorrect": false, "reaction": "Bukan, juruteknik! Pak Tani menunjuk ke arah petak kecilnya sambil tersenyum."}], "clue": "Hasilnya untuk dapur sendiri, bukan untuk dijual jauh."}]}'),
(802, 'e8_n1_s2', 'Soalan Pekebun: Kesan Getah dan Sawit', 'Pilih pernyataan yang betul tentang kesan industri getah dan kelapa sawit.', '3', 'Mengenal pasti kesan industri getah dan kelapa sawit.', '{"prompt": "Seorang pekebun bertanya kepadamu: yang manakah pernyataan yang betul tentang kesan industri getah dan kelapa sawit?", "options": [{"text": "Meningkatkan pendapatan negara, menyediakan peluang pekerjaan dan mewujudkan industri hiliran serta biodiesel.", "isCorrect": true}, {"text": "Hanya menyediakan peluang pekerjaan tanpa menambah pendapatan negara atau mewujudkan industri hiliran.", "isCorrect": false, "consequence": "Pekebun itu pulang dengan maklumat yang tidak lengkap. Dia menyangka industri ini tidak menambah pendapatan negara."}, {"text": "Menyebabkan semua ladang ditutup dan menghentikan industri biodiesel serta industri asas tani.", "isCorrect": false, "consequence": "Pekebun itu pulang dengan maklumat yang tersalah. Dia menyangka industri ini menghentikan industri lain."}], "aftermath": "Kesan industri getah dan kelapa sawit dijawab tidak tepat. Pekebun pulang dengan maklumat yang tersalah.", "turns": [{"after": 6, "options": [{"text": "Industri getah dan kelapa sawit.", "isCorrect": true, "reaction": "Tepat, juruteknik! Penoreh Getah mengangkat mangkuk susu getahnya seperti menyambut kemenangan."}, {"text": "Industri petroleum dan gas.", "isCorrect": false, "reaction": "Bukan, juruteknik! Penoreh Getah ketawa kerana minyak itu datang dari pelantar."}, {"text": "Industri pelancongan.", "isCorrect": false, "reaction": "Bukan, juruteknik! Penoreh Getah menggeleng sambil tersenyum."}], "clue": "Biodiesel dibangunkan hasil tanaman yang tumbuh di ladang."}]}'),
(803, 'e8_n1_s3', 'Padanan Pelantar: Kesan Petroleum dan Gas', 'Padankan setiap kumpulan dengan kesan industri petroleum dan gas.', '4', 'Mengenal pasti kesan industri petroleum dan gas.', '{"pairs": [{"text": "Usahawan", "pair": 1}, {"text": "Stesen minyak", "pair": 1}, {"text": "Meningkatkan pendapatan", "pair": 2}, {"text": "Penajaan sukan permotoran", "pair": 2}, {"text": "Pelajar", "pair": 3}, {"text": "Biasiswa", "pair": 3}, {"text": "Pekerja", "pair": 4}, {"text": "Peluang pekerjaan", "pair": 4}], "aftermath": "Kesan industri petroleum dan gas tersalah padan. Pelantar menghantar maklumat yang tidak tepat.", "turns": [{"after": 6, "options": [{"text": "Usahawan stesen minyak.", "isCorrect": true, "reaction": "Tepat, juruteknik! Jurutera mengangkat helmetnya sebagai tanda tabik."}, {"text": "Usahawan kedai bunga.", "isCorrect": false, "reaction": "Bukan, juruteknik! Jurutera ketawa kerana pelantar tiada bunga."}, {"text": "Usahawan kilang kasut.", "isCorrect": false, "reaction": "Bukan, juruteknik! Jurutera menggeleng sambil menunjuk ke arah stesen minyak."}], "clue": "Mereka menjual petrol yang diisi ke dalam kenderaan."}]}'),
(804, 'e8_n1_s4', 'Susun Garis Masa Kilang Kereta', 'Susun peristiwa industri automotif mengikut tahun.', '1', 'Mengenal pasti perkembangan industri automotif dan kegiatan pelancongan.', '{"timelineItems": [{"id": 1, "year": "1983", "text": "PROTON ditubuhkan", "why": "Tahun penubuhan PROTON ialah 1983."}, {"id": 2, "year": "1993", "text": "PERODUA ditubuhkan", "why": "Tahun penubuhan PERODUA ialah 1993."}, {"id": 3, "year": "2018", "text": "PROTON mengadakan usaha sama dengan Geely Holding Group", "why": "Usaha sama ini dibuat pada tahun 2018."}], "aftermath": "Garis masa kilang kereta tersalah susun. Tahun penubuhan PROTON dan PERODUA bertukar tempat.", "turns": [{"after": 7, "options": [{"text": "Pada tahun 1993.", "isCorrect": true, "reaction": "Tepat, juruteknik! Inspektor mengangguk dan sebuah kereta kecil berbunyi hon."}, {"text": "Pada tahun 1983.", "isCorrect": false, "reaction": "Itu tahun PROTON, juruteknik! Inspektor tersenyum sambil menggeleng."}, {"text": "Pada tahun 2018.", "isCorrect": false, "reaction": "Itu tahun usaha sama dengan Geely, juruteknik! Inspektor ketawa kecil."}], "clue": "Ia ditubuhkan sepuluh tahun selepas PROTON."}]}'),
(805, 'e8_n1_s5', 'Nyahkod Catatan Produk Petroleum', 'Baca catatan yang luntur dan tentukan satu lagi produk petroleum jenama Malaysia.', '5', 'Mengenal pasti keluaran barangan jenama Malaysia.', '{"clueText": "Catatan menulis: Produk petroleum jenama Malaysia ialah minyak petrol dan gas untuk memasak. Satu lagi produk sudah luntur dan tidak kelihatan, tetapi ia melincirkan enjin kenderaan.", "options": [{"text": "Minyak pelincir kenderaan.", "isCorrect": true}, {"text": "Minyak masak untuk dapur.", "isCorrect": false, "consequence": "Catatan itu dibaca dengan produk pertanian. Pelanggan menyangka minyak masak ialah produk petroleum."}, {"text": "Motosikal untuk perjalanan.", "isCorrect": false, "consequence": "Catatan itu dibaca dengan produk automotif. Pelanggan menyangka motosikal ialah produk petroleum."}], "aftermath": "Catatan produk petroleum disalah baca. Pelanggan keliru tentang kumpulan produk.", "turns": [{"after": 5, "options": [{"text": "Produk pertanian.", "isCorrect": true, "reaction": "Tepat, juruteknik! Pemilik kedai menepuk tangan dan rak itu berkilat."}, {"text": "Produk petroleum.", "isCorrect": false, "reaction": "Bukan, juruteknik! Pemilik kedai menggeleng kerana sabun satu kumpulan dengan minyak masak."}, {"text": "Produk automotif.", "isCorrect": false, "reaction": "Bukan, juruteknik! Pemilik kedai ketawa sambil menunjuk ke arah kereta mainan."}], "clue": "Sabun disenaraikan bersama minyak masak dan buah-buahan."}]}'),
(806, 'e8_n1_s6', 'Padanan Bandar: Tiga Pencapaian', 'Padankan setiap pencapaian dengan cirinya.', '4', 'Mengenal pasti pencapaian pembangunan, perhubungan dan perdagangan.', '{"pairs": [{"text": "Pembangunan", "pair": 1}, {"text": "Bangunan pencakar langit", "pair": 1}, {"text": "Perhubungan", "pair": 2}, {"text": "Jaringan perhubungan moden yang terancang", "pair": 2}, {"text": "Perdagangan", "pair": 3}, {"text": "Kegiatan e-dagang yang semakin berkembang", "pair": 3}], "aftermath": "Pencapaian ekonomi tersalah padan. Peta kemajuan bandar membawa maklumat yang tidak tepat.", "turns": [{"after": 5, "options": [{"text": "Kegiatan e-dagang.", "isCorrect": true, "reaction": "Tepat, juruteknik! Peniaga E-Dagang menekan butang hantar sambil ketawa."}, {"text": "Kegiatan jual beli secara tukar barang.", "isCorrect": false, "reaction": "Itu cara lama, juruteknik! Peniaga E-Dagang menggeleng sambil tersenyum."}, {"text": "Kegiatan jual beli di pasar kampung sahaja.", "isCorrect": false, "reaction": "Bukan, juruteknik! Peniaga E-Dagang menunjuk ke arah gudang e-dagang."}], "clue": "Jual beli dilakukan melalui telefon dan laman web."}]}'),
(807, 'e8_n2_s1', 'Padanan Borang Ciri Ekonomi', 'Padankan setiap ciri dengan jenis ekonomi yang betul.', '4', 'Membezakan ekonomi tradisional dan ekonomi komersial.', '{"pairs": [{"text": "Tradisional: peralatan", "pair": 1}, {"text": "Cangkul dan sabit", "pair": 1}, {"text": "Komersial: peralatan", "pair": 2}, {"text": "Mesin dan jentera penuai", "pair": 2}, {"text": "Tradisional: modal dan tenaga kerja", "pair": 3}, {"text": "Modal kecil, tenaga kerja sedikit", "pair": 3}, {"text": "Komersial: modal dan tenaga kerja", "pair": 4}, {"text": "Modal besar, tenaga kerja banyak", "pair": 4}, {"text": "Tradisional: hasil", "pair": 5}, {"text": "Keperluan sendiri dan keluarga", "pair": 5}, {"text": "Komersial: hasil", "pair": 6}, {"text": "Kegunaan tempatan dan eksport", "pair": 6}], "aftermath": "Borang ciri ekonomi tersalah padan. Inspektor mencop LULUS pada ciri yang tidak tepat.", "turns": [{"after": 7, "options": [{"text": "Ekonomi komersial.", "isCorrect": true, "reaction": "Tepat, inspektor! Petani Moden menekan cop LULUS di udara sambil ketawa."}, {"text": "Ekonomi tradisional.", "isCorrect": false, "reaction": "Itu pakai cangkul dan sabit, inspektor! Pak Tani menggeleng sambil tersenyum."}, {"text": "Ekonomi cangkul dan sabit.", "isCorrect": false, "reaction": "Itu ekonomi tradisional, inspektor! Petani Moden menunjuk ke arah jentera penuainya."}], "clue": "Mesin dan jentera penuai hadir bersama modal besar dan perladangan."}]}'),
(808, 'e8_n2_s2', 'Soalan Murid: Kesan Getah dan Sawit', 'Pilih pernyataan yang betul tentang kesan industri getah dan kelapa sawit.', '3', 'Mengenal pasti kesan industri getah dan kelapa sawit.', '{"prompt": "Seorang pekebun bertanya kepadamu: yang manakah pernyataan yang betul tentang kesan industri getah dan kelapa sawit?", "options": [{"text": "Memajukan industri asas tani dan membangunkan industri biodiesel selain meningkatkan pendapatan negara.", "isCorrect": true}, {"text": "Hanya mewujudkan industri hiliran tanpa menyediakan peluang pekerjaan kepada sesiapa pun di ladang.", "isCorrect": false, "consequence": "Pekebun itu pulang dengan maklumat yang tersalah. Dia menyangka industri ini tidak membuka pekerjaan."}, {"text": "Menurunkan pendapatan negara kerana semua hasil getah dan sawit tidak dieksport ke mana-mana.", "isCorrect": false, "consequence": "Pekebun itu pulang dengan maklumat yang tersalah. Dia menyangka industri ini merugikan negara."}], "aftermath": "Kesan industri getah dan kelapa sawit dijawab tidak tepat. Pekebun pulang dengan maklumat yang tersalah.", "turns": [{"after": 5, "options": [{"text": "Menyediakan peluang pekerjaan.", "isCorrect": true, "reaction": "Tepat, inspektor! Penoreh Getah tersenyum lebar dan mencop LULUS di borang."}, {"text": "Mewujudkan industri biodiesel.", "isCorrect": false, "reaction": "Itu kesan lain, inspektor! Penoreh Getah ketawa sambil menggeleng."}, {"text": "Meningkatkan pendapatan negara.", "isCorrect": false, "reaction": "Itu juga kesan lain, inspektor! Penoreh Getah tersenyum dan membetulkan jawapanmu."}], "clue": "Penoreh dan pekerja ladang mendapat kerja daripada industri ini."}]}'),
(809, 'e8_n2_s3', 'Nyahkod Papan Iklan Litar', 'Baca papan iklan yang luntur dan tentukan sukan yang dinaja oleh industri petroleum dan gas.', '5', 'Mengenal pasti kesan industri petroleum dan gas.', '{"clueText": "Papan iklan menulis: Industri petroleum dan gas meningkatkan pendapatan menerusi penajaan satu jenis sukan. Nama sukan itu sudah luntur dan tidak kelihatan, tetapi ia melibatkan motosikal dan kereta di litar.", "options": [{"text": "Sukan permotoran.", "isCorrect": true}, {"text": "Sukan renang kebangsaan.", "isCorrect": false, "consequence": "Papan iklan itu dibaca dengan sukan yang tidak berkaitan. Penonton menyangka syarikat petroleum menaja renang."}, {"text": "Sukan memanah tradisional.", "isCorrect": false, "consequence": "Papan iklan itu dibaca dengan sukan yang tidak berkaitan. Penonton menyangka syarikat petroleum menaja memanah."}], "aftermath": "Papan iklan litar disalah baca. Penonton keliru tentang sukan yang dinaja oleh syarikat petroleum.", "turns": [{"after": 4, "options": [{"text": "Biasiswa untuk pelajar.", "isCorrect": true, "reaction": "Tepat, inspektor! Jurutera mengangkat ibu jari dan sorakan litar bergema."}, {"text": "Pinjaman kereta untuk pelajar.", "isCorrect": false, "reaction": "Bukan, inspektor! Jurutera menggeleng sambil ketawa."}, {"text": "Tiket perlumbaan percuma sahaja.", "isCorrect": false, "reaction": "Bukan, inspektor! Jurutera tersenyum dan menunjuk ke arah pelajar yang belajar."}], "clue": "Bantuan itu untuk pelajar yang belajar di universiti."}]}'),
(810, 'e8_n2_s4', 'Misi Hutan: Bukti Tarikan Pelancong', 'Cari bukti tarikan pelancong pada gambar pantai dan hutan ini.', '2', 'Mengenal pasti perkembangan industri automotif dan kegiatan pelancongan.', '{"bgImage": "../assets/gameAsset/background/industri_pelancongan.png", "hotspots": [{"name": "Air terjun hutan: alam semula jadi memacu Tahun Melawat Malaysia", "top": "28%", "left": "29%"}, {"name": "Pelancong di jambatan gantung: tarikan alam semula jadi", "top": "22%", "left": "10%"}, {"name": "Gua batu kapur: tapak semula jadi yang menarik pelancong", "top": "62%", "left": "32%"}, {"name": "Pelancong bergambar di pantai: Tahun Melawat Malaysia", "top": "68%", "left": "72%"}], "aftermath": "Bukti tarikan pelancong tersalah cari. Inspektor menyangka tarikan pelancong hanyalah kilang kereta.", "turns": [{"after": 5, "options": [{"text": "Pada tahun 1983.", "isCorrect": true, "reaction": "Tepat, inspektor! Pemandu Pelancong menepuk tangan dan monyet belanda pun menoleh."}, {"text": "Pada tahun 1993.", "isCorrect": false, "reaction": "Itu tahun PERODUA, inspektor! Pemandu Pelancong menggeleng sambil tersenyum."}, {"text": "Pada tahun 2018.", "isCorrect": false, "reaction": "Itu tahun usaha sama dengan Geely, inspektor! Pemandu Pelancong ketawa kecil."}], "clue": "PROTON ditubuhkan lebih awal daripada PERODUA."}]}'),
(811, 'e8_n2_s5', 'Padanan Barisan Pemeriksaan Produk', 'Padankan setiap kumpulan produk dengan senarai produknya.', '4', 'Mengenal pasti keluaran barangan jenama Malaysia.', '{"pairs": [{"text": "Produk pertanian", "pair": 1}, {"text": "Minyak masak, durian, nanas dan sabun", "pair": 1}, {"text": "Produk petroleum", "pair": 2}, {"text": "Petrol, gas memasak dan minyak pelincir", "pair": 2}, {"text": "Produk automotif", "pair": 3}, {"text": "Motosikal dan kereta", "pair": 3}], "aftermath": "Produk jenama Malaysia tersalah padan. Cop LULUS dijatuhkan pada kumpulan yang tidak tepat.", "turns": [{"after": 6, "options": [{"text": "Produk petroleum.", "isCorrect": true, "reaction": "Tepat, inspektor! Pemilik Kedai mencop LULUS pada tong gas."}, {"text": "Produk pertanian.", "isCorrect": false, "reaction": "Bukan, inspektor! Pemilik Kedai menggeleng kerana gas bukan hasil tanaman."}, {"text": "Produk automotif.", "isCorrect": false, "reaction": "Bukan, inspektor! Pemilik Kedai ketawa sambil menunjuk ke arah kereta."}], "clue": "Gas itu datang daripada industri minyak dan gas."}]}'),
(812, 'e8_n2_s6', 'Misi Bandar: Bukti Tiga Pencapaian', 'Cari bukti pembangunan, perhubungan dan perdagangan pada gambar bandar ini.', '2', 'Mengenal pasti pencapaian pembangunan, perhubungan dan perdagangan.', '{"bgImage": "../assets/gameAsset/background/pencapaian_ekonomi_perhubungan_dan_perdagangan.png", "hotspots": [{"name": "Menara pencakar langit: pembangunan negara", "top": "20%", "left": "24%"}, {"name": "Jambatan, kereta api dan jalan raya: perhubungan moden yang terancang", "top": "62%", "left": "38%"}, {"name": "Gudang E-Dagang: perdagangan yang semakin berkembang", "top": "45%", "left": "78%"}, {"name": "Papan iklan carta menaik: e-dagang semakin berkembang", "top": "22%", "left": "90%"}], "aftermath": "Bukti pencapaian bandar tersalah cari. Inspektor mencop LULUS pada bukti yang tidak berkaitan.", "turns": [{"after": 5, "options": [{"text": "Kegiatan e-dagang.", "isCorrect": true, "reaction": "Tepat, inspektor! Peniaga E-Dagang mencop LULUS di skrin telefon."}, {"text": "Kegiatan tukar barang di pasar.", "isCorrect": false, "reaction": "Itu cara lama, inspektor! Peniaga E-Dagang menggeleng sambil tersenyum."}, {"text": "Kegiatan jual beli di pasar malam sahaja.", "isCorrect": false, "reaction": "Bukan, inspektor! Peniaga E-Dagang menunjuk ke arah gudang e-dagang."}], "clue": "Jual beli melalui telefon dan laman web yang semakin berkembang."}]}'),
(813, 'e8_n3_s1', 'Nyahkod Lembaran Nota Kampung', 'Baca lembaran nota yang luntur dan tentukan pasaran yang dituju oleh ekonomi komersial.', '5', 'Membezakan ekonomi tradisional dan ekonomi komersial.', '{"clueText": "Lembaran nota menulis: Ekonomi komersial dijalankan secara perladangan dengan peralatan moden. Hasilnya untuk kegunaan tempatan dan satu lagi pasaran. Pasaran itu sudah luntur dan tidak kelihatan, tetapi ia di luar negara.", "options": [{"text": "Eksport ke luar negara.", "isCorrect": true}, {"text": "Keperluan sendiri dan keluarga.", "isCorrect": false, "consequence": "Nota itu dibaca dengan ciri ekonomi tradisional. Pelanggan menyangka ladang komersial hanya untuk keluarga."}, {"text": "Pasar tani di hujung kampung.", "isCorrect": false, "consequence": "Nota itu dibaca dengan pasaran yang terlalu kecil. Pelanggan menyangka ladang komersial hanya berniaga di kampung."}], "aftermath": "Nota tentang ekonomi komersial disalah baca. Pelanggan menyangka ladang komersial hanya untuk keluarga.", "turns": [{"after": 6, "options": [{"text": "Cangkul dan sabit.", "isCorrect": true, "reaction": "Tepat, tauke! Pak Tani mengangkat cangkulnya seperti sebuah piala."}, {"text": "Mesin dan jentera penuai.", "isCorrect": false, "reaction": "Itu peralatan ekonomi komersial, tauke! Petani Moden menyampuk sambil ketawa."}, {"text": "Jentera pembajak berkuasa besar.", "isCorrect": false, "reaction": "Bukan, tauke! Pak Tani menggeleng kerana dia hanya ada alat mudah."}], "clue": "Peralatan mudah yang boleh dipegang dengan tangan sahaja."}]}'),
(814, 'e8_n3_s2', 'Padanan Rak: Kesan Getah dan Sawit', 'Padankan setiap kesan industri getah dan kelapa sawit dengan kata kerjanya.', '4', 'Mengenal pasti kesan industri getah dan kelapa sawit.', '{"pairs": [{"text": "Pendapatan negara", "pair": 1}, {"text": "Ditingkatkan", "pair": 1}, {"text": "Peluang pekerjaan", "pair": 2}, {"text": "Disediakan", "pair": 2}, {"text": "Industri hiliran", "pair": 3}, {"text": "Diwujudkan", "pair": 3}, {"text": "Industri asas tani", "pair": 4}, {"text": "Dimajukan", "pair": 4}, {"text": "Industri biodiesel", "pair": 5}, {"text": "Dibangunkan", "pair": 5}], "aftermath": "Kesan industri getah dan kelapa sawit tersalah padan. Rak di kedai membawa maklumat yang tidak tepat.", "turns": [{"after": 6, "options": [{"text": "Industri getah dan kelapa sawit.", "isCorrect": true, "reaction": "Tepat, tauke! Petani Moden mengangkat buah sawit sebagai tanda kemenangan."}, {"text": "Industri petroleum dan gas.", "isCorrect": false, "reaction": "Bukan, tauke! Penoreh Getah ketawa kerana itu industri di pelantar."}, {"text": "Industri automotif dan pelancongan.", "isCorrect": false, "reaction": "Bukan, tauke! Petani Moden menggeleng sambil menunjuk ke arah ladang."}], "clue": "Industri ini tumbuh di ladang, daripada pokok getah dan kelapa sawit."}]}'),
(815, 'e8_n3_s3', 'Soalan Pelanggan: Kesan Petroleum dan Gas', 'Pilih pernyataan yang betul tentang kesan industri petroleum dan gas.', '3', 'Mengenal pasti kesan industri petroleum dan gas.', '{"prompt": "Seorang pelanggan bertanya kepadamu: yang manakah pernyataan yang betul tentang kesan industri petroleum dan gas?", "options": [{"text": "Mewujudkan peluang pekerjaan, melahirkan usahawan stesen minyak dan menyediakan biasiswa.", "isCorrect": true}, {"text": "Hanya melahirkan usahawan stesen minyak dan tidak menyediakan sebarang biasiswa kepada pelajar.", "isCorrect": false, "consequence": "Pelanggan itu pulang dengan maklumat yang tidak lengkap. Dia menyangka biasiswa tidak pernah disediakan."}, {"text": "Meningkatkan pendapatan menerusi penajaan tetapi tidak mewujudkan sebarang peluang pekerjaan.", "isCorrect": false, "consequence": "Pelanggan itu pulang dengan maklumat yang tersalah. Dia menyangka industri ini tidak membuka pekerjaan."}], "aftermath": "Kesan industri petroleum dan gas dijawab tidak tepat. Pelanggan pulang dengan maklumat yang tersalah.", "turns": [{"after": 5, "options": [{"text": "Melalui penajaan sukan permotoran.", "isCorrect": true, "reaction": "Tepat, tauke! Jurutera tersenyum dan ombak pun menyambut jawapanmu."}, {"text": "Melalui penjualan tiket kapal terbang.", "isCorrect": false, "reaction": "Bukan, tauke! Jurutera menggeleng sambil ketawa."}, {"text": "Melalui penanaman padi di pelantar.", "isCorrect": false, "reaction": "Bukan, tauke! Jurutera ketawa kerana tiada sawah di tengah laut."}], "clue": "Syarikat petroleum menaja perlumbaan motosikal dan kereta."}]}'),
(816, 'e8_n3_s4', 'Susun Kad Automotif di Kaunter', 'Susun peristiwa industri automotif mengikut tahun.', '1', 'Mengenal pasti perkembangan industri automotif dan kegiatan pelancongan.', '{"timelineItems": [{"id": 1, "year": "1983", "text": "PROTON ditubuhkan", "why": "PROTON ditubuhkan lebih awal daripada PERODUA."}, {"id": 2, "year": "1993", "text": "PERODUA ditubuhkan", "why": "PERODUA ditubuhkan selepas PROTON."}, {"id": 3, "year": "2018", "text": "PROTON mengadakan usaha sama dengan Geely Holding Group", "why": "Usaha sama ini ialah peristiwa terkini dalam senarai."}], "aftermath": "Kad automotif tersalah susun. Pelanggan membaca tahun penubuhan yang tidak tepat.", "turns": [{"after": 7, "options": [{"text": "Geely Holding Group.", "isCorrect": true, "reaction": "Tepat, tauke! Inspektor menepuk bumbung kereta sambil tersenyum."}, {"text": "Syarikat PERODUA.", "isCorrect": false, "reaction": "Bukan, tauke! PERODUA ialah syarikat lain yang ditubuhkan pada 1993."}, {"text": "Syarikat PETRONAS.", "isCorrect": false, "reaction": "Bukan, tauke! Inspektor ketawa dan menggeleng-geleng."}], "clue": "Syarikat luar negara yang namanya mengandungi perkataan Group."}]}'),
(817, 'e8_n3_s5', 'Soalan Pelanggan: Produk Jenama Malaysia', 'Pilih pernyataan yang betul tentang kumpulan produk jenama Malaysia.', '3', 'Mengenal pasti keluaran barangan jenama Malaysia.', '{"prompt": "Seorang pelanggan bertanya kepadamu: yang manakah pernyataan yang betul tentang kumpulan produk jenama Malaysia?", "options": [{"text": "Pertanian: minyak masak dan sabun; petroleum: petrol dan gas memasak; automotif: motosikal dan kereta.", "isCorrect": true}, {"text": "Pertanian: motosikal dan sabun; petroleum: petrol dan gas memasak; automotif: minyak masak dan kereta.", "isCorrect": false, "consequence": "Pelanggan itu pulang dengan senarai yang tersalah. Dia menyangka motosikal ialah produk pertanian."}, {"text": "Pertanian: minyak masak dan sabun; petroleum: motosikal dan petrol; automotif: gas memasak dan kereta.", "isCorrect": false, "consequence": "Pelanggan itu pulang dengan senarai yang tersalah. Dia menyangka gas memasak ialah produk automotif."}], "aftermath": "Produk jenama Malaysia dijawab tidak tepat. Pelanggan pulang dengan senarai yang tersalah.", "turns": [{"after": 6, "options": [{"text": "Buah durian dan buah nanas.", "isCorrect": true, "reaction": "Tepat, tauke! Petani Moden menghulur sebiji durian sebagai hadiah."}, {"text": "Minyak petrol dan gas memasak.", "isCorrect": false, "reaction": "Itu produk petroleum, tauke! Petani Moden menggeleng sambil tersenyum."}, {"text": "Motosikal dan kereta.", "isCorrect": false, "reaction": "Itu produk automotif, tauke! Petani Moden ketawa kecil."}], "clue": "Hasil tanaman dari ladang dan kebun."}]}'),
(818, 'e8_n3_s6', 'Nyahkod Nota Perdagangan', 'Baca nota yang luntur dan tentukan kegiatan perdagangan yang semakin berkembang.', '5', 'Mengenal pasti pencapaian pembangunan, perhubungan dan perdagangan.', '{"clueText": "Nota menulis: Perdagangan negara kini ditandai oleh satu kegiatan yang semakin berkembang. Nama kegiatan itu sudah luntur dan tidak kelihatan, tetapi ia dilakukan melalui telefon dan laman web.", "options": [{"text": "Kegiatan e-dagang.", "isCorrect": true}, {"text": "Kegiatan tukar barang di pasar.", "isCorrect": false, "consequence": "Nota itu dibaca dengan cara perdagangan lama. Pelanggan menyangka perdagangan masih tukar barang."}, {"text": "Kegiatan menoreh getah di kebun.", "isCorrect": false, "consequence": "Nota itu dibaca dengan kegiatan yang tidak berkaitan. Pelanggan menyangka perdagangan ialah menoreh getah."}], "aftermath": "Nota tentang perdagangan disalah baca. Pelanggan menyangka perdagangan masih secara tukar barang.", "turns": [{"after": 5, "options": [{"text": "Jaringan perhubungan moden yang terancang.", "isCorrect": true, "reaction": "Tepat, tauke! Peniaga E-Dagang menekan butang hantar sambil ketawa."}, {"text": "Bangunan pencakar langit yang tinggi.", "isCorrect": false, "reaction": "Itu pembangunan, tauke! Peniaga E-Dagang menggeleng sambil tersenyum."}, {"text": "Kegiatan e-dagang yang berkembang.", "isCorrect": false, "reaction": "Itu perdagangan, tauke! Peniaga E-Dagang ketawa kecil."}], "clue": "Kereta api, jambatan layang dan lebuh raya yang bersambung."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e8_n1_s1', 'hint', 'Tradisional: kecil-kecilan, cangkul dan sabit, modal kecil, tenaga kerja sedikit, untuk keperluan sendiri dan keluarga. Komersial: perladangan, mesin dan jentera penuai, modal besar, tenaga kerja banyak, tempatan dan eksport.', NULL, NULL),
(801, NULL, 'hint', 'Cari dua cangkul, rumah kayu dan petak sawah kecil. Semuanya tanda ekonomi tradisional.', 'Ekonomi tradisional: dijalankan secara kecil-kecilan, peralatan mudah (cangkul, sabit), modal kecil, tenaga kerja sedikit, untuk keperluan sendiri atau keluarga. Ekonomi komersial: secara perladangan, peralatan moden (mesin, jentera penuai), modal besar, tenaga kerja banyak, untuk kegunaan tempatan dan eksport.', 'Hebat! Empat bukti ditemui dan Pak Tani mengangguk puas.'),
(NULL, 'e8_n1_s2', 'hint', 'Lima kesan: pendapatan negara, peluang pekerjaan, industri hiliran, industri asas tani dan industri biodiesel.', NULL, NULL),
(802, NULL, 'hint', 'Ingat lima kesan: pendapatan, pekerjaan, hiliran, asas tani dan biodiesel.', 'Industri getah dan kelapa sawit: meningkatkan pendapatan negara, menyediakan peluang pekerjaan, mewujudkan industri hiliran, memajukan industri asas tani dan membangunkan industri biodiesel.', 'Betul! Kebun getah bergema dengan tepukan dan mangkuk getah bergoyang riang.'),
(NULL, 'e8_n1_s3', 'hint', 'Empat kesan: peluang pekerjaan, usahawan stesen minyak, pendapatan menerusi penajaan sukan permotoran dan biasiswa.', NULL, NULL),
(803, NULL, 'hint', 'Usahawan dengan stesen minyak, pelajar dengan biasiswa. Dua lagi: pendapatan dan pekerja.', 'Industri petroleum dan gas: mewujudkan peluang pekerjaan, melahirkan usahawan stesen minyak, meningkatkan pendapatan menerusi penajaan sukan permotoran dan menyediakan biasiswa.', 'Betul! Empat kad bertemu pasangannya dan siren pelantar berbunyi riang.'),
(NULL, 'e8_n1_s4', 'hint', 'PROTON 1983 (usaha sama Geely 2018), PERODUA 1993. Tahun Melawat Malaysia dipacu tapak sejarah, alam semula jadi, keharmonian budaya, agropelancongan, sukan, muzik dan pameran antarabangsa.', NULL, NULL),
(804, NULL, 'hint', 'Susun dari yang paling awal: PROTON, PERODUA, kemudian usaha sama dengan Geely.', 'Industri automotif: PROTON ditubuhkan pada 1983 (usaha sama dengan Geely Holding Group pada 2018) dan PERODUA pada 1993. Industri pelancongan: Tahun Melawat Malaysia dipacu oleh tapak dan bangunan bersejarah, alam semula jadi, keharmonian budaya, agropelancongan, serta penganjuran sukan, muzik dan pameran antarabangsa.', 'Betul! Tiga peristiwa tersusun dan barisan kereta bergerak lancar.'),
(NULL, 'e8_n1_s5', 'hint', 'Pertanian: minyak masak, durian, nanas, sabun. Petroleum: petrol, gas memasak, minyak pelincir. Automotif: motosikal dan kereta.', NULL, NULL),
(805, NULL, 'hint', 'Satu lagi produk petroleum yang melincirkan enjin kenderaan, bukan minyak masak atau motosikal.', 'Produk pertanian: minyak masak, buah durian, buah nanas dan sabun. Produk petroleum: minyak petrol, gas untuk memasak dan minyak pelincir kenderaan. Produk automotif: motosikal dan kereta.', 'Betul! Catatan jelas semula dan pelanggan pulang dengan senyuman.'),
(NULL, 'e8_n1_s6', 'hint', 'Pembangunan: bangunan pencakar langit. Perhubungan: jaringan moden yang terancang. Perdagangan: e-dagang yang semakin berkembang.', NULL, NULL),
(806, NULL, 'hint', 'Pembangunan dengan pencakar langit, perhubungan dengan jaringan moden, perdagangan dengan e-dagang.', 'Pembangunan: kewujudan bangunan pencakar langit. Perhubungan: jaringan perhubungan moden yang terancang. Perdagangan: kegiatan e-dagang yang semakin berkembang.', 'Betul! Tiga kad bertemu pasangannya dan lampu bandar menyala terang.'),
(NULL, 'e8_n2_s1', 'hint', 'Tradisional: cangkul dan sabit, modal kecil, tenaga kerja sedikit, untuk keluarga. Komersial: perladangan, mesin dan jentera penuai, modal besar, tenaga kerja banyak, tempatan dan eksport.', NULL, NULL),
(807, NULL, 'hint', 'Tradisional: cangkul dan sabit, modal kecil, untuk keluarga. Komersial: mesin, modal besar, tempatan dan eksport.', 'Ekonomi tradisional: kecil-kecilan, peralatan mudah (cangkul, sabit), modal kecil, tenaga kerja sedikit, untuk keperluan sendiri atau keluarga. Ekonomi komersial: perladangan, peralatan moden (mesin, jentera penuai), modal besar, tenaga kerja banyak, kegunaan tempatan dan eksport.', 'Betul! Enam ciri bertemu pasangannya dan cop LULUS jatuh dengan kuat.'),
(NULL, 'e8_n2_s2', 'hint', 'Lima kesan: pendapatan negara, peluang pekerjaan, industri hiliran, industri asas tani dan industri biodiesel.', NULL, NULL),
(808, NULL, 'hint', 'Ingat lima kesan: pendapatan, pekerjaan, hiliran, asas tani dan biodiesel.', 'Industri getah dan kelapa sawit: meningkatkan pendapatan negara, menyediakan peluang pekerjaan, mewujudkan industri hiliran, memajukan industri asas tani dan membangunkan industri biodiesel.', 'Betul! Ladang bergema dengan tepukan dan borang pun dicop LULUS.'),
(NULL, 'e8_n2_s3', 'hint', 'Petroleum dan gas: peluang pekerjaan, usahawan stesen minyak, pendapatan menerusi penajaan sukan permotoran, biasiswa.', NULL, NULL),
(809, NULL, 'hint', 'Sukan itu berlangsung di litar dengan motosikal dan kereta.', 'Industri petroleum dan gas: mewujudkan peluang pekerjaan, melahirkan usahawan stesen minyak, meningkatkan pendapatan menerusi penajaan sukan permotoran dan menyediakan biasiswa.', 'Betul! Papan iklan jelas semula dan litar bergema dengan sorakan.'),
(NULL, 'e8_n2_s4', 'hint', 'Tahun Melawat Malaysia dipacu tapak sejarah, alam semula jadi, keharmonian budaya, agropelancongan, sukan, muzik dan pameran antarabangsa. PROTON 1983 (Geely 2018), PERODUA 1993.', NULL, NULL),
(810, NULL, 'hint', 'Cari air terjun, jambatan gantung, gua batu kapur dan pelancong di pantai.', 'Industri automotif: PROTON ditubuhkan pada 1983 (usaha sama dengan Geely Holding Group pada 2018) dan PERODUA pada 1993. Industri pelancongan: Tahun Melawat Malaysia dipacu oleh tapak dan bangunan bersejarah, alam semula jadi, keharmonian budaya, agropelancongan, serta penganjuran sukan, muzik dan pameran antarabangsa.', 'Hebat! Empat bukti ditemui dan Pemandu Pelancong bersorak.'),
(NULL, 'e8_n2_s5', 'hint', 'Pertanian: minyak masak, durian, nanas, sabun. Petroleum: petrol, gas memasak, minyak pelincir. Automotif: motosikal dan kereta.', NULL, NULL),
(811, NULL, 'hint', 'Pertanian ialah minyak masak, durian, nanas dan sabun. Petroleum ialah petrol, gas dan pelincir.', 'Produk pertanian: minyak masak, buah durian, buah nanas dan sabun. Produk petroleum: minyak petrol, gas untuk memasak dan minyak pelincir kenderaan. Produk automotif: motosikal dan kereta.', 'Betul! Tiga kumpulan bertemu pasangannya dan barisan pemeriksaan lulus.'),
(NULL, 'e8_n2_s6', 'hint', 'Pembangunan: pencakar langit. Perhubungan: jaringan moden yang terancang. Perdagangan: e-dagang yang semakin berkembang.', NULL, NULL),
(812, NULL, 'hint', 'Cari menara pencakar langit, jambatan dan kereta api, gudang e-dagang dan papan carta.', 'Pembangunan: kewujudan bangunan pencakar langit. Perhubungan: jaringan perhubungan moden yang terancang. Perdagangan: kegiatan e-dagang yang semakin berkembang.', 'Hebat! Semua bukti ditemui dan pemeriksaan besar pun lulus!'),
(NULL, 'e8_n3_s1', 'hint', 'Tradisional: kecil-kecilan, cangkul dan sabit, untuk keluarga. Komersial: perladangan, mesin dan jentera penuai, tempatan dan eksport.', NULL, NULL),
(813, NULL, 'hint', 'Pasaran itu di luar negara. Ingat hasil komersial untuk tempatan dan eksport.', 'Ekonomi tradisional: kecil-kecilan, peralatan mudah (cangkul, sabit), modal kecil, tenaga kerja sedikit, untuk keperluan sendiri atau keluarga. Ekonomi komersial: perladangan, peralatan moden (mesin, jentera penuai), modal besar, tenaga kerja banyak, kegunaan tempatan dan eksport.', 'Betul! Lembaran nota jelas semula dan Pak Tani bertepuk tangan.'),
(NULL, 'e8_n3_s2', 'hint', 'Pendapatan negara ditingkatkan, peluang pekerjaan disediakan, industri hiliran diwujudkan, industri asas tani dimajukan, industri biodiesel dibangunkan.', NULL, NULL),
(814, NULL, 'hint', 'Pendapatan ditingkatkan, pekerjaan disediakan, hiliran diwujudkan, asas tani dimajukan dan biodiesel dibangunkan.', 'Industri getah dan kelapa sawit: meningkatkan pendapatan negara, menyediakan peluang pekerjaan, mewujudkan industri hiliran, memajukan industri asas tani dan membangunkan industri biodiesel.', 'Betul! Lima kad bertemu pasangannya dan rak itu berseri-seri.'),
(NULL, 'e8_n3_s3', 'hint', 'Petroleum dan gas: peluang pekerjaan, usahawan stesen minyak, pendapatan menerusi penajaan sukan permotoran, biasiswa.', NULL, NULL),
(815, NULL, 'hint', 'Ingat empat kesan: pekerjaan, usahawan stesen minyak, penajaan sukan permotoran dan biasiswa.', 'Industri petroleum dan gas: mewujudkan peluang pekerjaan, melahirkan usahawan stesen minyak, meningkatkan pendapatan menerusi penajaan sukan permotoran dan menyediakan biasiswa.', 'Betul! Kedai bergema dengan tepukan dan tin-tin minyak berkilat di rak.'),
(NULL, 'e8_n3_s4', 'hint', 'Pelancongan: tapak sejarah, alam semula jadi, keharmonian budaya, agropelancongan, sukan, muzik, pameran antarabangsa. Automotif: PROTON 1983 (Geely 2018), PERODUA 1993.', NULL, NULL),
(816, NULL, 'hint', '1983 PROTON, 1993 PERODUA, 2018 usaha sama dengan Geely.', 'Industri automotif: PROTON ditubuhkan pada 1983 (usaha sama dengan Geely Holding Group pada 2018) dan PERODUA pada 1993. Industri pelancongan: Tahun Melawat Malaysia dipacu oleh tapak dan bangunan bersejarah, alam semula jadi, keharmonian budaya, agropelancongan, serta penganjuran sukan, muzik dan pameran antarabangsa.', 'Betul! Tiga kad tersusun kemas dan kaunter pun berkilat.'),
(NULL, 'e8_n3_s5', 'hint', 'Pertanian: minyak masak, durian, nanas, sabun. Petroleum: petrol, gas memasak, minyak pelincir. Automotif: motosikal dan kereta.', NULL, NULL),
(817, NULL, 'hint', 'Pertanian dengan hasil tanaman dan sabun, petroleum dengan petrol dan gas, automotif dengan motosikal dan kereta.', 'Produk pertanian: minyak masak, buah durian, buah nanas dan sabun. Produk petroleum: minyak petrol, gas untuk memasak dan minyak pelincir kenderaan. Produk automotif: motosikal dan kereta.', 'Betul! Rak-rak berkilat dan pelanggan pulang dengan beg penuh barangan.'),
(NULL, 'e8_n3_s6', 'hint', 'Pembangunan: pencakar langit. Perhubungan: jaringan moden yang terancang. Perdagangan: e-dagang yang semakin berkembang.', NULL, NULL),
(818, NULL, 'hint', 'Kegiatan itu dilakukan melalui telefon dan laman web, jadi ia ialah e-dagang.', 'Pembangunan: kewujudan bangunan pencakar langit. Perhubungan: jaringan perhubungan moden yang terancang. Perdagangan: kegiatan e-dagang yang semakin berkembang.', 'Betul! Nota jelas semula dan laman web kedai pun dibuka!');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(141, 801, NULL, 'Tugasku ialah memastikan mesin ladang terus berjalan supaya ekonomi tidak berhenti. Jika juruteknik berhenti, jentera pun senyap, {nama}. Terima kasih kerana meminjamkan tanganmu!', 1),
(141, 801, NULL, 'Ekonomi negara berkembang daripada cangkul kepada jentera, dan daripada ladang kepada industri. Apabila kita mengenali setiap kegiatan, kita menghargai kemajuan yang dicapai.', 2),
(141, 801, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, juruteknik yang tangannya sentiasa berminyak dan kotak peralatannya sentiasa berbunyi. Enjin sudah dihidupkan, kembara bermula! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(144, 801, 'e8_n1_s1', 'Anak muda juruteknik, lihat sawah ini! Ekonomi tradisional dijalankan secara kecil-kecilan, tahu? Satu keluarga, satu petak kecil.', 1),
(NULL, 801, 'e8_n1_s1', 'Nampak bersih dan sederhana, Pak Tani. Apakah peralatan Pak Tani?', 2),
(144, 801, 'e8_n1_s1', 'Peralatan mudah sahaja: cangkul dan sabit. Modal kecil, tenaga kerja pun sedikit. Hasilnya untuk keperluan sendiri dan keluarga.', 3),
(145, 801, 'e8_n1_s1', 'Ha, tengok pula ladangku! Ekonomi komersial dijalankan secara perladangan. Peralatannya moden, seperti mesin dan jentera penuai!', 4),
(145, 801, 'e8_n1_s1', 'Modalnya besar, tenaga kerjanya banyak. Hasilnya untuk kegunaan tempatan dan juga dieksport ke luar negara!', 5),
(NULL, 801, 'e8_n1_s1', 'Wah, bezanya jelas! Tradisional: kecil-kecilan, cangkul dan sabit, modal kecil, tenaga sedikit, untuk keluarga. Komersial: ladang, jentera, modal besar, tenaga banyak, tempatan dan eksport!', 6),
(144, 801, 'e8_n1_s1', 'Pandai! Sebelum cari bukti pada gambar sawah ini, soalan Pak Tani: ekonomi tradisional untuk keperluan siapa?', 7),
(146, 801, 'e8_n1_s2', 'Juruteknik! Ini kebun getah. Industri getah dan kelapa sawit meningkatkan pendapatan negara. Titisan susu getah ini bernilai!', 1),
(146, 801, 'e8_n1_s2', 'Industri ini juga menyediakan peluang pekerjaan. Aku menoreh getah, kau membaiki mesin. Ramai orang ada kerja!', 2),
(145, 801, 'e8_n1_s2', 'Di ladang sawit pula, industri ini mewujudkan industri hiliran. Hasilnya diproses menjadi pelbagai barangan, bukan dijual mentah sahaja!', 3),
(145, 801, 'e8_n1_s2', 'Ia juga memajukan industri asas tani, dan membangunkan industri biodiesel. Bahan api daripada sawit pun ada!', 4),
(NULL, 801, 'e8_n1_s2', 'Lima kesan: pendapatan negara, peluang pekerjaan, industri hiliran, industri asas tani dan industri biodiesel. Mudah diingat!', 5),
(146, 801, 'e8_n1_s2', 'Cuba satu soalan: industri biodiesel dibangunkan hasil industri apa?', 6),
(147, 801, 'e8_n1_s3', 'Juruteknik, selamat datang ke pelantar minyak! Industri petroleum dan gas mewujudkan peluang pekerjaan. Aku jurutera, kau juruteknik, kita sama-sama bekerja!', 1),
(147, 801, 'e8_n1_s3', 'Industri ini juga melahirkan usahawan stesen minyak. Dari pelantar ke stesen, ramai orang berniaga!', 2),
(147, 801, 'e8_n1_s3', 'Pendapatan juga meningkat menerusi penajaan sukan permotoran. Syarikat menaja perlumbaan, rakyat pula bersorak!', 3),
(147, 801, 'e8_n1_s3', 'Dan industri ini menyediakan biasiswa. Ramai pelajar belajar dengan tenang berkat biasiswa ini!', 4),
(NULL, 801, 'e8_n1_s3', 'Empat kesan: peluang pekerjaan, usahawan stesen minyak, pendapatan menerusi penajaan sukan permotoran dan biasiswa. Siap catat!', 5),
(147, 801, 'e8_n1_s3', 'Soalan pantas: industri petroleum dan gas melahirkan usahawan jenis apa?', 6),
(142, 801, 'e8_n1_s4', 'Juruteknik! Selamat datang ke kilang kereta. Industri automotif bermula dengan PROTON pada tahun 1983. Satu lagi nama besar ialah PERODUA, pada tahun 1993.', 1),
(142, 801, 'e8_n1_s4', 'PROTON juga mengadakan usaha sama dengan Geely Holding Group pada tahun 2018. Kereta rakyat, kilang kita!', 2),
(NULL, 801, 'e8_n1_s4', 'PROTON 1983, PERODUA 1993, Geely 2018. Tapi apa pula kaitan industri pelancongan di sini?', 3),
(148, 801, 'e8_n1_s4', 'Aku pemandu pelancong! Kempen Tahun Melawat Malaysia dipacu oleh keistimewaan tapak dan bangunan bersejarah serta alam semula jadi.', 4),
(148, 801, 'e8_n1_s4', 'Keharmonian budaya dan agropelancongan juga memacunya. Pelancong suka melihat ladang dan kebun!', 5),
(148, 801, 'e8_n1_s4', 'Penganjuran sukan, muzik dan pameran antarabangsa pun menarik pelancong. Banyak sebab untuk melawat Malaysia!', 6),
(142, 801, 'e8_n1_s4', 'Sebelum susun garis masa, soalan inspektor: PERODUA ditubuhkan pada tahun berapa?', 7),
(143, 801, 'e8_n1_s5', 'Juruteknik! Selamat datang ke kedai barangan jenama Malaysia. Produk pertanian: minyak masak, buah durian, buah nanas dan sabun!', 1),
(143, 801, 'e8_n1_s5', 'Produk petroleum pula: minyak petrol, gas untuk memasak dan minyak pelincir kenderaan. Tong gas dan botol minyak semua ada!', 2),
(145, 801, 'e8_n1_s5', 'Produk automotif: motosikal dan kereta. Dua roda dan empat roda, semuanya jenama Malaysia!', 3),
(NULL, 801, 'e8_n1_s5', 'Tiga kumpulan: pertanian, petroleum dan automotif. Eh, catatan tentang produk petroleum ini luntur sedikit!', 4),
(143, 801, 'e8_n1_s5', 'Tolong baca nanti, tetapi dahulu satu soalan: sabun termasuk dalam kumpulan produk apa?', 5),
(149, 801, 'e8_n1_s6', 'Juruteknik! Lihat bandar ini. Pembangunan bermakna kewujudan bangunan pencakar langit yang menjulang!', 1),
(149, 801, 'e8_n1_s6', 'Perhubungan pula: jaringan perhubungan moden yang terancang. Kereta api, jambatan layang dan lebuh raya semuanya bersambung kemas!', 2),
(149, 801, 'e8_n1_s6', 'Dan perdagangan: kegiatan e-dagang yang semakin berkembang. Aku jual barang melalui telefon dan sampai ke pintu rumah!', 3),
(NULL, 801, 'e8_n1_s6', 'Wah, maju betul! Pembangunan, perhubungan dan perdagangan. Jom padankan!', 4),
(149, 801, 'e8_n1_s6', 'Soalan e-dagang untuk juruteknik: apakah kegiatan perdagangan yang semakin berkembang itu?', 5),
(142, 802, NULL, 'Tugasku ialah memastikan setiap produk lulus pemeriksaan sebelum sampai ke tangan rakyat. Jika inspektor berhenti memeriksa, mutu pun terabai, {nama}. Terima kasih kerana meminjamkan matamu!', 1),
(142, 802, NULL, 'Ekonomi yang kukuh dibina daripada banyak kegiatan yang saling menyokong. Apabila kita memeriksa setiap satu dengan teliti, kita menghargai kemajuan negara.', 2),
(142, 802, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, inspektor yang membawa papan klip dan cop LULUS di poket. Satu pemeriksaan besar bermula hari ini! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(NULL, 802, 'e8_n2_s1', 'Inspektor kilang turun ke ladang! Borang pemeriksaan pertama: ekonomi tradisional atau komersial? Lihat dahulu, baru cop LULUS!', 1),
(145, 802, 'e8_n2_s1', 'Inspektor, ladang ini komersial! Dijalankan secara perladangan, dengan peralatan moden seperti mesin dan jentera penuai.', 2),
(145, 802, 'e8_n2_s1', 'Modal besar, tenaga kerja banyak. Hasilnya untuk kegunaan tempatan dan juga dieksport!', 3),
(144, 802, 'e8_n2_s1', 'Hmmph, aku masih setia dengan cara tradisional. Dijalankan kecil-kecilan, dengan cangkul dan sabit.', 4),
(144, 802, 'e8_n2_s1', 'Modal kecil, tenaga kerja sedikit. Hasilnya untuk keperluan sendiri dan keluarga. Cukup untuk dapur sendiri!', 5),
(NULL, 802, 'e8_n2_s1', 'Dua jenis ekonomi, dua borang. Aku mahu padankan ciri dengan jenisnya. Cop sedia!', 6),
(145, 802, 'e8_n2_s1', 'Soalan inspektor, dengar baik-baik: mesin dan jentera penuai digunakan dalam ekonomi jenis apa?', 7),
(146, 802, 'e8_n2_s2', 'Inspektor, selamat datang ke ladang getah! Industri getah dan kelapa sawit meningkatkan pendapatan negara.', 1),
(146, 802, 'e8_n2_s2', 'Ia menyediakan peluang pekerjaan dan mewujudkan industri hiliran. Dari pokok ke kilang, sambung-menyambung!', 2),
(145, 802, 'e8_n2_s2', 'Ia juga memajukan industri asas tani, dan membangunkan industri biodiesel. Lima kesan semuanya, inspektor!', 3),
(NULL, 802, 'e8_n2_s2', 'Lima kesan: pendapatan negara, peluang pekerjaan, industri hiliran, industri asas tani dan biodiesel. Cop LULUS untuk kelimanya!', 4),
(146, 802, 'e8_n2_s2', 'Eh, nanti dulu! Soalan semakan: kesan manakah yang berkait dengan peluang kerja untuk penoreh macam aku?', 5),
(147, 802, 'e8_n2_s3', 'Inspektor, kau tahu syarikat petroleum menaja perlumbaan ini? Industri petroleum dan gas meningkatkan pendapatan menerusi penajaan sukan permotoran!', 1),
(147, 802, 'e8_n2_s3', 'Industri ini juga mewujudkan peluang pekerjaan, melahirkan usahawan stesen minyak dan menyediakan biasiswa.', 2),
(NULL, 802, 'e8_n2_s3', 'Ada sorakan, ada enjin! Empat kesan dalam satu litar: pekerjaan, usahawan stesen minyak, penajaan sukan permotoran dan biasiswa.', 3),
(147, 802, 'e8_n2_s3', 'Papan iklan itu luntur, inspektor. Tapi dahulu, jawab soalanku: apakah yang disediakan kepada pelajar oleh industri ini?', 4),
(148, 802, 'e8_n2_s4', 'Inspektor, kau tengok pantai ini? Kempen Tahun Melawat Malaysia dipacu oleh keistimewaan tapak dan bangunan bersejarah serta alam semula jadi!', 1),
(148, 802, 'e8_n2_s4', 'Keharmonian budaya dan agropelancongan juga menarik pelancong. Penganjuran sukan, muzik dan pameran antarabangsa pun sama!', 2),
(NULL, 802, 'e8_n2_s4', 'Aku inspektor kilang kereta. Hairan juga kerjaku datang ke hutan! Tetapi PROTON ditubuhkan pada tahun 1983 dan PERODUA pada tahun 1993.', 3),
(148, 802, 'e8_n2_s4', 'Dan pada tahun 2018, PROTON mengadakan usaha sama dengan Geely Holding Group. Kereta kita sudah maju, inspektor!', 4),
(148, 802, 'e8_n2_s4', 'Jom cari bukti tarikan pelancong pada gambar ini! Tetapi dahulu, soalan: PROTON ditubuhkan pada tahun berapa?', 5),
(NULL, 802, 'e8_n2_s5', 'Barisan pemeriksaan terakhir! Inspektor mahu semak barangan jenama Malaysia sebelum lulus. Satu persatu, ya!', 1),
(143, 802, 'e8_n2_s5', 'Produk pertanian: minyak masak, buah durian, buah nanas dan sabun, inspektor!', 2),
(143, 802, 'e8_n2_s5', 'Produk petroleum: minyak petrol, gas untuk memasak dan minyak pelincir kenderaan.', 3),
(143, 802, 'e8_n2_s5', 'Produk automotif: motosikal dan kereta. Yang ini memang bidang inspektor, bukan?', 4),
(NULL, 802, 'e8_n2_s5', 'Baik! Tiga kumpulan, sembilan produk. Aku padankan semuanya sekarang!', 5),
(143, 802, 'e8_n2_s5', 'Soalan semakan: gas untuk memasak ialah produk apa?', 6),
(149, 802, 'e8_n2_s6', 'Inspektor! Lihat bandar ini. Pembangunan bermakna kewujudan bangunan pencakar langit.', 1),
(149, 802, 'e8_n2_s6', 'Perhubungan pula jaringan perhubungan moden yang terancang. Kereta api dan jambatan layang bersambung kemas!', 2),
(149, 802, 'e8_n2_s6', 'Dan perdagangan: e-dagang yang semakin berkembang. Barang terus sampai ke pintu rumah!', 3),
(NULL, 802, 'e8_n2_s6', 'Pemeriksaan terakhir: cari bukti pembangunan, perhubungan dan perdagangan pada gambar ini.', 4),
(149, 802, 'e8_n2_s6', 'Sebelum itu, soalan inspektor: yang manakah kegiatan perdagangan yang semakin berkembang?', 5),
(143, 803, NULL, 'Tugasku ialah memperkenalkan barangan buatan negara sendiri kepada setiap pelanggan. Jika pemilik kedai berhenti bercerita, rak pun sunyi, {nama}. Terima kasih kerana meminjamkan suaramu!', 1),
(143, 803, NULL, 'Setiap barangan di rak membawa cerita tentang kegiatan ekonomi di sebaliknya. Apabila kita mengenalinya, kita lebih menghargai barangan buatan negara sendiri.', 2),
(143, 803, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemilik kedai yang bangga dengan setiap rak di kedainya. Papan tanda sudah dipasang dan pintu dibuka! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(144, 803, 'e8_n3_s1', 'Tauke kedai! Pak Tani jual beras sendiri di kampung ini. Ekonomi tradisional dijalankan kecil-kecilan, dengan peralatan mudah seperti cangkul dan sabit.', 1),
(144, 803, 'e8_n3_s1', 'Modal kecil, tenaga kerja sedikit, dan hasilnya untuk keperluan sendiri dan keluarga. Kedai Pak Tani cuma di pangkin rumah!', 2),
(145, 803, 'e8_n3_s1', 'Aku pula petani moden, tauke! Ekonomi komersial secara perladangan, dengan peralatan moden seperti mesin dan jentera penuai.', 3),
(145, 803, 'e8_n3_s1', 'Modal besar dan tenaga kerja banyak. Hasilnya untuk kegunaan tempatan dan eksport. Kedai tauke pun boleh jual ke luar negara!', 4),
(NULL, 803, 'e8_n3_s1', 'Dua jenis ekonomi, kontras yang jelas. Tetapi lembaran nota ini luntur, tolong nyahkod!', 5),
(144, 803, 'e8_n3_s1', 'Sebelum itu soalan Pak Tani: peralatan ekonomi tradisional apa yang aku guna?', 6),
(145, 803, 'e8_n3_s2', 'Tauke, lihat ladang sawit ini! Industri getah dan kelapa sawit meningkatkan pendapatan negara.', 1),
(146, 803, 'e8_n3_s2', 'Dan menyediakan peluang pekerjaan. Aku menoreh getah, jiranku mengendalikan jentera, semua ada kerja!', 2),
(145, 803, 'e8_n3_s2', 'Industri hiliran pun diwujudkan, dan industri asas tani dimajukan.', 3),
(146, 803, 'e8_n3_s2', 'Industri biodiesel pun dibangunkan! Hasil sawit boleh menjadi bahan api, tauke.', 4),
(NULL, 803, 'e8_n3_s2', 'Lima kesan, lima rak di kedai! Aku padankan kesan dengan kata kerjanya sekarang.', 5),
(145, 803, 'e8_n3_s2', 'Soalan pantas, tauke: lima kesan semuanya datang daripada industri apa?', 6),
(147, 803, 'e8_n3_s3', 'Tauke! Pelantar ini mengeluarkan minyak dan gas yang tauke jual dalam tong dan botol. Industri petroleum dan gas mewujudkan peluang pekerjaan.', 1),
(147, 803, 'e8_n3_s3', 'Ia melahirkan usahawan stesen minyak, dan meningkatkan pendapatan menerusi penajaan sukan permotoran.', 2),
(147, 803, 'e8_n3_s3', 'Industri ini juga menyediakan biasiswa. Pelajar pintar belajar dengan tenang!', 3),
(NULL, 803, 'e8_n3_s3', 'Empat kesan, empat tin minyak di rak. Aku jawab soalan pelanggan dahulu!', 4),
(147, 803, 'e8_n3_s3', 'Tauke, soalan: yang manakah cara industri petroleum dan gas meningkatkan pendapatan?', 5),
(148, 803, 'e8_n3_s4', 'Tauke, litar ini tarikan pelancong! Penganjuran sukan, muzik dan pameran antarabangsa menarik pelancong ke Malaysia.', 1),
(148, 803, 'e8_n3_s4', 'Kempen Tahun Melawat Malaysia dipacu oleh tapak dan bangunan bersejarah, serta alam semula jadi.', 2),
(148, 803, 'e8_n3_s4', 'Keharmonian budaya dan agropelancongan juga memacunya. Banyak pilihan untuk pelancong!', 3),
(142, 803, 'e8_n3_s4', 'Aku inspektor kilang, tauke. Industri automotif bermula dengan PROTON pada tahun 1983, kemudian PERODUA pada tahun 1993.', 4),
(142, 803, 'e8_n3_s4', 'Pada tahun 2018, PROTON mengadakan usaha sama dengan Geely Holding Group. Kereta kita makin maju!', 5),
(NULL, 803, 'e8_n3_s4', 'Susun kad dahulu, tauke! 1983, 1993, 2018. Tapi aku tanya dahulu satu soalan.', 6),
(142, 803, 'e8_n3_s4', 'Soalan inspektor: PROTON mengadakan usaha sama dengan syarikat apa pada tahun 2018?', 7),
(NULL, 803, 'e8_n3_s5', 'Inilah rak kebanggaan kedaiku! Barangan jenama Malaysia di mana-mana.', 1),
(145, 803, 'e8_n3_s5', 'Tauke, produk pertanian: minyak masak, buah durian, buah nanas dan sabun. Semuanya bermula daripada ladang kita!', 2),
(147, 803, 'e8_n3_s5', 'Produk petroleum: minyak petrol, gas untuk memasak dan minyak pelincir kenderaan. Tong gas itu datang dari pelantar aku!', 3),
(142, 803, 'e8_n3_s5', 'Produk automotif: motosikal dan kereta. Semua keluaran Malaysia, tauke!', 4),
(NULL, 803, 'e8_n3_s5', 'Tiga rak penuh! Sekarang pelanggan bertanya soalan di kaunter.', 5),
(145, 803, 'e8_n3_s5', 'Tauke, tolong jawab soalan pelanggan ini. Yang manakah produk pertanian?', 6),
(149, 803, 'e8_n3_s6', 'Tauke, kedai tauke patut ada laman web! Perdagangan e-dagang semakin berkembang. Pelanggan boleh membeli dari rumah!', 1),
(149, 803, 'e8_n3_s6', 'Pembangunan juga ketara: kewujudan bangunan pencakar langit yang menghiasi langit bandar.', 2),
(149, 803, 'e8_n3_s6', 'Dan perhubungan: jaringan perhubungan moden yang terancang, supaya barang cepat sampai.', 3),
(NULL, 803, 'e8_n3_s6', 'Pembangunan, perhubungan dan perdagangan! Tiga kejayaan ekonomi negara. Tetapi nota ini luntur sedikit, tolong bantu!', 4),
(149, 803, 'e8_n3_s6', 'Soalan peniaga: yang manakah termasuk dalam perhubungan?', 5);
INSERT INTO QuestionBank (bankID, eraID) VALUES (8, 8)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(801, 8, 'Ekonomi yang dijalankan secara kecil-kecilan dengan peralatan mudah dikenali sebagai apa?', 'Ekonomi komersial secara perladangan', 'Ekonomi tradisional', 'Ekonomi moden berasaskan mesin', 'Ekonomi eksport berskala besar', 'B', 'Fikirkan cangkul dan sabit.', 'Ekonomi tradisional dijalankan secara kecil-kecilan, menggunakan peralatan mudah, modal kecil dan tenaga kerja yang sedikit.'),
(802, 8, 'Antara yang berikut, yang manakah peralatan ekonomi tradisional?', 'Cangkul dan sabit', 'Mesin dan jentera penuai', 'Jentera pembajak moden', 'Mesin penuai kelapa sawit', 'A', 'Peralatan mudah, tiada mesin.', 'Peralatan ekonomi tradisional ialah peralatan mudah seperti cangkul dan sabit.'),
(803, 8, 'Untuk siapakah hasil ekonomi tradisional digunakan?', 'Kegunaan tempatan dan eksport ke luar negara', 'Pasaran antarabangsa dan syarikat besar', 'Syarikat perladangan yang menggunakan jentera', 'Keperluan sendiri dan keluarga', 'D', 'Dijalankan secara kecil-kecilan.', 'Hasil ekonomi tradisional digunakan untuk keperluan sendiri atau keluarga.'),
(804, 8, 'Bagaimanakah modal dan tenaga kerja dalam ekonomi tradisional?', 'Modal kecil dan tenaga kerja sedikit', 'Modal besar dan tenaga kerja banyak', 'Modal besar dan tenaga kerja sedikit', 'Modal kecil dan tenaga kerja banyak', 'A', 'Kedua-duanya kecil atau sedikit.', 'Ekonomi tradisional menggunakan modal kecil dan tenaga kerja yang sedikit.'),
(805, 8, 'Ekonomi komersial dijalankan secara apa?', 'Secara kecil-kecilan di halaman rumah', 'Secara perladangan', 'Secara tukar barang dengan jiran', 'Secara sara diri untuk keluarga', 'B', 'Kawasan yang luas dan teratur.', 'Ekonomi komersial dijalankan secara perladangan.'),
(806, 8, 'Antara yang berikut, yang manakah peralatan ekonomi komersial?', 'Cangkul dan sabit kecil', 'Cangkul dan parang tangan', 'Mesin dan jentera penuai', 'Sabit dan bakul rotan', 'C', 'Peralatan moden berskala besar.', 'Ekonomi komersial menggunakan peralatan moden seperti mesin dan jentera penuai.'),
(807, 8, 'Bagaimanakah modal dan tenaga kerja dalam ekonomi komersial?', 'Modal besar dan tenaga kerja banyak', 'Modal kecil dan tenaga kerja sedikit', 'Modal kecil dan tenaga kerja banyak', 'Modal besar dan tenaga kerja sedikit', 'A', 'Perladangan memerlukan banyak sumber.', 'Ekonomi komersial menggunakan modal besar dan tenaga kerja yang banyak.'),
(808, 8, 'Untuk kegunaan apakah hasil ekonomi komersial?', 'Keperluan sendiri dan keluarga sahaja', 'Keperluan jiran dekat dan saudara mara', 'Kegunaan tempatan dan eksport', 'Keperluan dapur sendiri pada hujung minggu', 'C', 'Dijual jauh sehingga ke luar negara.', 'Hasil ekonomi komersial digunakan untuk kegunaan tempatan dan eksport.'),
(809, 8, 'Apakah kesan industri getah dan kelapa sawit terhadap pendapatan negara?', 'Menurunkan pendapatan negara', 'Meningkatkan pendapatan negara', 'Tidak mengubah pendapatan negara', 'Menggantikan semua pendapatan lain', 'B', 'Pendapatan itu menjadi lebih banyak.', 'Industri getah dan kelapa sawit meningkatkan pendapatan negara.'),
(810, 8, 'Apakah yang disediakan oleh industri getah dan kelapa sawit kepada rakyat?', 'Biasiswa kepada semua pelajar', 'Penajaan sukan permotoran', 'Tiket kempen pelancongan', 'Peluang pekerjaan', 'D', 'Penoreh dan pekerja ladang mendapat kerja.', 'Industri getah dan kelapa sawit menyediakan peluang pekerjaan.'),
(811, 8, 'Industri manakah diwujudkan hasil perkembangan getah dan kelapa sawit untuk memproses hasilnya?', 'Industri stesen minyak', 'Industri hiliran', 'Industri penajaan sukan', 'Industri kereta nasional', 'B', 'Ia mengambil hasil dan menjadikannya produk lain.', 'Industri getah dan kelapa sawit mewujudkan industri hiliran.'),
(812, 8, 'Industri manakah dimajukan oleh perkembangan getah dan kelapa sawit?', 'Industri asas tani', 'Industri pelancongan antarabangsa', 'Industri automotif nasional', 'Industri petroleum dan gas', 'A', 'Industri ini berkait dengan pertanian.', 'Industri getah dan kelapa sawit memajukan industri asas tani.'),
(813, 8, 'Industri bahan api manakah dibangunkan oleh industri getah dan kelapa sawit?', 'Industri petrol dan gas memasak', 'Industri minyak pelincir kenderaan', 'Industri bateri kereta elektrik', 'Industri biodiesel', 'D', 'Bahan api daripada hasil kelapa sawit.', 'Industri getah dan kelapa sawit membangunkan industri biodiesel.'),
(814, 8, 'Yang manakah pernyataan yang betul tentang kesan industri getah dan kelapa sawit?', 'Meningkatkan pendapatan negara, melahirkan usahawan stesen minyak dan menyediakan biasiswa', 'Menyediakan biasiswa, menaja sukan permotoran dan melahirkan usahawan stesen minyak', 'Meningkatkan pendapatan negara, mewujudkan industri hiliran dan membangunkan industri biodiesel', 'Mewujudkan PROTON dan PERODUA serta membangunkan kempen Tahun Melawat Malaysia', 'C', 'Ingat lima kesan: pendapatan, pekerjaan, hiliran, asas tani dan biodiesel.', 'Lima kesan industri getah dan kelapa sawit ialah pendapatan negara, peluang pekerjaan, industri hiliran, industri asas tani dan industri biodiesel.'),
(815, 8, 'Siapakah yang dilahirkan oleh industri petroleum dan gas di sepanjang jalan raya?', 'Usahawan kedai bunga', 'Usahawan kilang kasut', 'Usahawan stesen minyak', 'Usahawan pasar tani', 'C', 'Mereka menjual petrol kepada pemandu.', 'Industri petroleum dan gas melahirkan usahawan stesen minyak.'),
(816, 8, 'Bagaimanakah industri petroleum dan gas meningkatkan pendapatan?', 'Menerusi penanaman padi di pelantar', 'Menerusi penjualan tiket kapal terbang', 'Menerusi penubuhan kebun getah', 'Menerusi penajaan sukan permotoran', 'D', 'Syarikat petroleum menaja perlumbaan.', 'Industri petroleum dan gas meningkatkan pendapatan menerusi penajaan sukan permotoran.'),
(817, 8, 'Apakah yang disediakan kepada pelajar oleh industri petroleum dan gas?', 'Pinjaman kereta', 'Tiket perlumbaan percuma', 'Tanah ladang kelapa sawit', 'Biasiswa', 'D', 'Pelajar belajar dengan bantuan kewangan.', 'Industri petroleum dan gas menyediakan biasiswa.'),
(818, 8, 'Apakah yang diwujudkan oleh industri petroleum dan gas bagi rakyat?', 'Hanya hutan simpan', 'Peluang pekerjaan', 'Hanya tapak bersejarah', 'Hanya ladang getah', 'B', 'Jurutera dan juruteknik bekerja di pelantar.', 'Industri petroleum dan gas mewujudkan peluang pekerjaan.'),
(819, 8, 'Yang manakah pernyataan yang betul tentang industri petroleum dan gas?', 'Melahirkan usahawan stesen minyak tetapi tidak menyediakan sebarang biasiswa kepada pelajar', 'Menyediakan biasiswa tetapi tidak mewujudkan sebarang peluang pekerjaan kepada rakyat', 'Mewujudkan peluang pekerjaan, melahirkan usahawan stesen minyak dan menyediakan biasiswa', 'Meningkatkan pendapatan menerusi penajaan tetapi tidak melahirkan sebarang usahawan', 'C', 'Ingat empat kesan: pekerjaan, usahawan, penajaan dan biasiswa.', 'Empat kesan industri petroleum dan gas ialah peluang pekerjaan, usahawan stesen minyak, pendapatan menerusi penajaan sukan permotoran dan biasiswa.'),
(820, 8, 'Antara yang berikut, yang manakah BUKAN kesan industri petroleum dan gas?', 'Membangunkan industri biodiesel', 'Melahirkan usahawan stesen minyak', 'Menyediakan biasiswa', 'Mewujudkan peluang pekerjaan', 'A', 'Industri biodiesel berkait dengan kelapa sawit.', 'Industri biodiesel dibangunkan oleh industri getah dan kelapa sawit, bukan oleh industri petroleum dan gas.'),
(821, 8, 'Pada tahun berapakah PROTON ditubuhkan?', '1983', '1993', '2018', '1973', 'A', 'Ia ditubuhkan lebih awal daripada PERODUA.', 'PROTON ditubuhkan pada tahun 1983.'),
(822, 8, 'Pada tahun berapakah PERODUA ditubuhkan?', '1983', '1993', '2018', '1963', 'B', 'Ia ditubuhkan sepuluh tahun selepas PROTON.', 'PERODUA ditubuhkan pada tahun 1993.'),
(823, 8, 'PROTON mengadakan usaha sama pada tahun 2018 dengan syarikat apa?', 'PERODUA Holding Group', 'Geely Holding Group', 'Petronas Holding Group', 'Proton Holding Group', 'B', 'Syarikat luar negara.', 'PROTON mengadakan usaha sama dengan Geely Holding Group pada tahun 2018.'),
(824, 8, 'Yang manakah susunan yang betul mengikut tahun dalam industri automotif?', 'PERODUA 1983, PROTON 1993, usaha sama PROTON dengan Geely 2018', 'PROTON 1983, usaha sama dengan Geely 1993, PERODUA 2018', 'Usaha sama dengan Geely 1983, PROTON 1993, PERODUA 2018', 'PROTON 1983, PERODUA 1993, usaha sama PROTON dengan Geely 2018', 'D', 'Mulakan dengan tahun yang paling awal.', 'PROTON (1983), PERODUA (1993), usaha sama PROTON dengan Geely Holding Group (2018).'),
(825, 8, 'Antara PROTON dan PERODUA, yang manakah ditubuhkan lebih awal?', 'PERODUA', 'Kedua-duanya pada tahun yang sama', 'Geely Holding Group', 'PROTON', 'D', 'Bandingkan 1983 dengan 1993.', 'PROTON ditubuhkan pada 1983, manakala PERODUA pada 1993.'),
(826, 8, 'Kempen apakah yang dipacu oleh keistimewaan tapak sejarah, alam semula jadi dan keharmonian budaya?', 'Tahun Wawasan Malaysia', 'Tahun Melawat Malaysia', 'Tahun Perpaduan Malaysia', 'Tahun Perladangan Malaysia', 'B', 'Kempen ini mengajak pelancong datang.', 'Kempen Tahun Melawat Malaysia dipacu oleh pelbagai keistimewaan negara.'),
(827, 8, 'Yang manakah pemacu kempen Tahun Melawat Malaysia?', 'Penutupan semua taman negara', 'Kenaikan harga makanan di hotel', 'Penghentian semua pameran antarabangsa', 'Tapak dan bangunan bersejarah', 'D', 'Pelancong gemar melawat tempat lama yang bernilai.', 'Tapak dan bangunan bersejarah ialah salah satu pemacu kempen Tahun Melawat Malaysia.'),
(828, 8, 'Yang manakah keistimewaan semula jadi yang memacu kempen Tahun Melawat Malaysia?', 'Gudang e-dagang', 'Kilang kereta nasional', 'Alam semula jadi', 'Pelantar minyak di laut', 'C', 'Hutan, air terjun dan pantai.', 'Alam semula jadi memacu kempen Tahun Melawat Malaysia.'),
(829, 8, 'Pelancongan yang berkait dengan ladang dan kebun dikenali sebagai apa?', 'Eko-industri', 'Pelancongan sukan', 'Agropelancongan', 'Pelancongan angkasa', 'C', 'Pelancong menikmati suasana pertanian.', 'Agropelancongan ialah salah satu pemacu kempen Tahun Melawat Malaysia.'),
(830, 8, 'Penganjuran apakah yang turut menarik pelancong ke Malaysia?', 'Sukan, muzik dan pameran antarabangsa', 'Pasar malam tempatan sahaja', 'Mesyuarat jemaah menteri sahaja', 'Pertandingan tanam padi sahaja', 'A', 'Acara besar yang disertai peserta luar negara.', 'Penganjuran sukan, muzik dan pameran antarabangsa turut menarik pelancong.'),
(831, 8, 'Antara yang berikut, yang manakah BUKAN pemacu kempen Tahun Melawat Malaysia?', 'Keharmonian budaya negara', 'Agropelancongan di ladang', 'Penutupan semua tapak bersejarah', 'Alam semula jadi yang indah', 'C', 'Pemacu menarik pelancong, bukan menjauhkan mereka.', 'Tapak bersejarah memacu kempen itu, jadi penutupannya bukan pemacu.'),
(832, 8, 'Yang manakah produk pertanian jenama Malaysia?', 'Minyak petrol, gas memasak dan minyak pelincir', 'Minyak masak, buah durian, buah nanas dan sabun', 'Motosikal, kereta dan minyak pelincir', 'Minyak petrol, buah durian dan motosikal', 'B', 'Hasil tanaman dan olahannya.', 'Produk pertanian ialah minyak masak, buah durian, buah nanas dan sabun.'),
(833, 8, 'Buah durian termasuk dalam kumpulan produk apa?', 'Produk pertanian', 'Produk petroleum', 'Produk automotif', 'Produk perhubungan', 'A', 'Hasil tanaman.', 'Buah durian ialah produk pertanian jenama Malaysia.'),
(834, 8, 'Yang manakah produk petroleum jenama Malaysia?', 'Minyak masak, buah durian, sabun dan gas untuk memasak', 'Minyak petrol, gas untuk memasak dan minyak pelincir kenderaan', 'Motosikal, kereta, minyak petrol dan gas untuk memasak', 'Buah nanas, minyak petrol, sabun dan kereta jenama nasional', 'B', 'Hasil minyak dan gas.', 'Produk petroleum ialah minyak petrol, gas untuk memasak dan minyak pelincir kenderaan.'),
(835, 8, 'Gas untuk memasak termasuk dalam kumpulan produk apa?', 'Produk pertanian', 'Produk automotif', 'Produk petroleum', 'Produk perladangan', 'C', 'Ia berasal daripada industri minyak dan gas.', 'Gas untuk memasak ialah produk petroleum.'),
(836, 8, 'Yang manakah produk automotif jenama Malaysia?', 'Minyak petrol dan kereta', 'Motosikal dan kereta', 'Sabun dan motosikal', 'Gas memasak dan kereta', 'B', 'Kenderaan berenjin.', 'Produk automotif ialah motosikal dan kereta.'),
(837, 8, 'Sabun termasuk dalam kumpulan produk apa?', 'Produk petroleum', 'Produk automotif', 'Produk pertanian', 'Produk pelancongan', 'C', 'Ia disenaraikan bersama minyak masak.', 'Sabun ialah produk pertanian jenama Malaysia.'),
(838, 8, 'Minyak pelincir kenderaan termasuk dalam kumpulan produk apa?', 'Produk pertanian', 'Produk automotif', 'Produk petroleum', 'Produk pelancongan', 'C', 'Ia dibuat daripada hasil minyak.', 'Minyak pelincir kenderaan ialah produk petroleum.'),
(839, 8, 'Yang manakah padanan produk dan kumpulannya yang betul?', 'Buah nanas dengan produk pertanian', 'Gas memasak dengan produk automotif', 'Motosikal dengan produk pertanian', 'Minyak petrol dengan produk pertanian', 'A', 'Fikirkan dari mana produk itu datang.', 'Buah nanas ialah produk pertanian jenama Malaysia.'),
(840, 8, 'Apakah tanda pembangunan dalam pencapaian ekonomi Malaysia?', 'Kewujudan kebun getah di kampung sahaja', 'Kewujudan sawah padi di kampung sahaja', 'Kewujudan pasar tani di kampung sahaja', 'Kewujudan bangunan pencakar langit', 'D', 'Bangunan yang menjulang tinggi di bandar.', 'Pembangunan ditandai oleh kewujudan bangunan pencakar langit.'),
(841, 8, 'Apakah yang dimaksudkan dengan perhubungan dalam pencapaian ekonomi Malaysia?', 'Jaringan perhubungan lama yang tidak teratur', 'Hanya jalan kampung sahaja', 'Hanya perhubungan melalui pos', 'Jaringan perhubungan moden yang terancang', 'D', 'Kereta api, jambatan layang dan lebuh raya.', 'Perhubungan ialah jaringan perhubungan moden yang terancang.'),
(842, 8, 'Apakah kegiatan perdagangan yang semakin berkembang di Malaysia?', 'Kegiatan e-dagang', 'Kegiatan tukar barang di pasar', 'Kegiatan menoreh getah di kebun', 'Kegiatan membajak sawah tradisional', 'A', 'Jual beli menggunakan telefon dan internet.', 'Perdagangan ditandai oleh kegiatan e-dagang yang semakin berkembang.'),
(843, 8, 'Yang manakah padanan yang betul bagi pencapaian ekonomi Malaysia?', 'Pembangunan dengan kegiatan e-dagang', 'Perhubungan dengan jaringan moden yang terancang', 'Perdagangan dengan bangunan pencakar langit', 'Perhubungan dengan jual beli secara tukar barang', 'B', 'Setiap tajuk ada ciri yang tersendiri.', 'Pembangunan: pencakar langit; perhubungan: jaringan moden terancang; perdagangan: e-dagang.'),
(844, 8, 'Yang manakah susunan pencapaian yang betul bagi pembangunan, perhubungan dan perdagangan?', 'E-dagang, pencakar langit, jaringan moden yang terancang', 'Jaringan moden yang terancang, e-dagang, pencakar langit', 'Pencakar langit, e-dagang, jaringan moden yang terancang', 'Pencakar langit, jaringan moden yang terancang, e-dagang', 'D', 'Ikut urutan tajuk: pembangunan, perhubungan dan perdagangan.', 'Pembangunan ialah pencakar langit, perhubungan ialah jaringan moden yang terancang dan perdagangan ialah e-dagang.'),
(845, 8, 'Yang manakah kegiatan ekonomi pemacu kemajuan negara?', 'Getah dan kelapa sawit, petroleum dan gas, automotif serta pelancongan', 'Getah dan kelapa sawit, sawah padi, nelayan serta perikanan laut', 'Petroleum dan gas, tenusu, perikanan serta kraf tangan kampung', 'Automotif, perikanan, tenusu serta kraf tangan kampung lama', 'A', 'Empat kegiatan utama.', 'Kegiatan ekonomi pemacu ialah industri getah dan kelapa sawit, petroleum dan gas, automotif serta pelancongan.'),
(846, 8, 'Ladang kelapa sawit yang menggunakan jentera penuai dan mengeksport hasil tergolong dalam ekonomi apa?', 'Ekonomi komersial', 'Ekonomi tradisional', 'Ekonomi untuk keluarga sahaja', 'Ekonomi kecil-kecilan', 'A', 'Perhatikan peralatan dan pasarannya.', 'Perladangan dengan peralatan moden dan hasil untuk eksport ialah ekonomi komersial.'),
(847, 8, 'Industri manakah mewujudkan industri hiliran dan industri biodiesel?', 'Industri petroleum dan gas', 'Industri automotif', 'Industri getah dan kelapa sawit', 'Industri pelancongan', 'C', 'Hasil tanaman diproses menjadi produk lain.', 'Industri hiliran dan biodiesel diwujudkan oleh industri getah dan kelapa sawit.'),
(848, 8, 'Industri manakah melahirkan usahawan stesen minyak?', 'Industri petroleum dan gas', 'Industri getah dan kelapa sawit', 'Industri automotif', 'Industri pelancongan', 'A', 'Stesen minyak menjual petrol.', 'Industri petroleum dan gas melahirkan usahawan stesen minyak.'),
(849, 8, 'Industri manakah ditandai oleh penubuhan PROTON dan PERODUA?', 'Industri pelancongan', 'Industri getah dan kelapa sawit', 'Industri petroleum dan gas', 'Industri automotif', 'D', 'Kereta nasional.', 'PROTON dan PERODUA ialah nama besar dalam industri automotif.'),
(850, 8, 'Yang manakah pernyataan yang betul tentang ekonomi tradisional dan ekonomi komersial?', 'Tradisional menggunakan modal besar dan jentera; komersial menggunakan modal kecil', 'Tradisional menggunakan cangkul dan sabit; komersial menggunakan mesin dan jentera penuai', 'Tradisional dijalankan secara perladangan; komersial dijalankan secara kecil-kecilan', 'Tradisional untuk eksport ke luar negara; komersial untuk keperluan keluarga sahaja', 'B', 'Bandingkan peralatan, modal dan hasil.', 'Ekonomi tradisional menggunakan peralatan mudah seperti cangkul dan sabit, manakala ekonomi komersial menggunakan peralatan moden seperti mesin dan jentera penuai.');
