-- ====================================================================
-- SejarahWira  |  ERA 8: Kemajuan Ekonomi Malaysia  |  seed_era8.sql
-- 3 naratif (6 + 6 + 6 babak = 18 babak), setiap babak ada 1 quest, serta 50 soalan.
--
-- SETIAP naratif merangkumi enam topik yang sama: (1) ekonomi tradisional dan komersial, (2) industri getah dan kelapa
-- sawit, (3) industri petroleum dan gas, (4) industri automotif dan pelancongan, (5) barangan jenama Malaysia,
-- (6) pembangunan, perhubungan dan perdagangan. Naratif hanya berbeza pada peranan, suara, watak sampingan dan jenis cabaran.
--
-- Pelajar MERASUK jasad watak rekaan (peranan naratif):
--   Naratif 1 (Dari Cangkul ke Jentera: Kembara Juruteknik) = Juruteknik Mesin Ladang (NPC 141)
--   Naratif 2 (Pemeriksaan Mutu Ekonomi Negara)             = Inspektor Kilang Automotif (NPC 142)
--   Naratif 3 (Kedai Jenama Malaysia: Cerita Setiap Rak)    = Pemilik Kedai Jenama Malaysia (NPC 143)
-- Baris dialog tanpa penutur (npcID NULL) ialah baris "Pemain" / "kau" yang dituturkan tokoh peranan.
-- Baris naratif tanpa babak (sceneID NULL): 1 = tugas bersejarah, 2 = pembuka pengajaran,
--   3 = pengenalan peranan oleh Pendekar Bayang.
-- Setiap quest ada "aftermath" (Akibat jika salah), pilihan salah jenis 3/5 ada "consequence",
-- dan satu "Giliran Anda" (turns). Data sahaja (tiada jadual atau lajur baharu).
-- Lencana, artifak dan kemajuan era TIDAK disentuh.
--
-- Jalankan SELEPAS seed.sql (NPC 141-149 dibuat di sini):
--   mysql --default-character-set=utf8mb4 -u root -p <nama_db> < database/seed_era8.sql
-- Selamat dijalankan berulang kali (kandungan Era 8 lama dipadam dahulu). Era lain tidak disentuh.
--
-- NOTA: kandungan ekonomi mengikut bahan asal sahaja; tiada angka atau fakta tambahan dimasukkan.
-- ====================================================================
SET NAMES utf8mb4;
START TRANSACTION;

-- 1. Buang kandungan Era 8 lama (babak, dialog, quest, sokongan dipadam sekali: ON DELETE CASCADE).
DELETE FROM Narrative WHERE eraID = 8;

-- 2. NPC baharu Era 8 (nama fail gambar mengikut folder npc sebenar).
ON DUPLICATE KEY UPDATE name = VALUES(name), biography = VALUES(biography), contribution = VALUES(contribution), asset = VALUES(asset);

-- 3. Naratif

-- 4. Babak (sceneStoryline = kad garis masa dalam suara "kau"; asset = latar belakang)

-- 5. Quest (1 Susun Garis Masa, 2 Cari Bukti, 3 Bantu Tokoh, 4 Padanan, 5 Nyahkod Clue)
--    instruction = taklimat misi, description = objektif pembelajaran

-- 6. Sokongan: baris babak = petunjuk babak; baris quest = bisikan (hint), catatan diari (explanation), pujian (feedback)

-- 7. Dialog: baris peranan (tanpa babak) dan dialog babak

-- 8. Bank soalan Era 8 (50 soalan aneka pilihan, ID 801-850)
ON DUPLICATE KEY UPDATE eraID = VALUES(eraID);

DELETE FROM Question WHERE bankID = 8;


COMMIT;